const webhookData = $('Webhook Trigger').item.json;
const body = webhookData.body || webhookData;

const rawName = (body.name || '').trim();
const rawEmail = (body.email || '').trim().toLowerCase();
const rawCompany = (body.company || '').trim();
const rawService = (body.serviceInterest || body.roleOrInterest || 'AI Chatbot & Web Development').trim();
const rawPhone = (body.phone || '').trim();
const rawMessage = (body.message || '').trim();
const rawSource = (body.source || 'geza-ai-services-website').trim();

if (!rawName) throw new Error('Name is required');
if (!rawEmail || !rawEmail.includes('@')) {
  throw new Error('Valid email address is required');
}
if (!rawMessage) throw new Error('Message is required');

const submissionId = 'srv_' + Date.now().toString(36) + '_' + Math.random().toString(36).substring(2, 7);
const now = new Date();
const formattedDate = now.toUTCString();

const emailSubject = `🚀 New Client Lead: ${rawName}${rawCompany ? ' (' + rawCompany + ')' : ''} — ${rawService}`;

function escapeHtml(str) {
  if (!str) return '';
  return str.replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
}

const emailHtml = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background-color: #FAF8F2; margin: 0; padding: 24px; color: #1C211A; }
    .email-container { max-width: 600px; margin: 0 auto; background: #FFFFFF; border-radius: 24px; overflow: hidden; border: 1px solid #E3E7DC; box-shadow: 0 8px 28px rgba(28,33,26,0.08); }
    .header { background: #1C211A; color: #FFFFFF; padding: 26px 28px; text-align: left; border-bottom: 4px solid #A4B885; }
    .header h1 { margin: 0; font-size: 20px; font-weight: 700; letter-spacing: -0.02em; color: #FFF6A1; }
    .header p { margin: 6px 0 0 0; font-size: 13px; color: #D4DDD0; }
    .content { padding: 28px; }
    .badge { display: inline-block; background: #FFF6A1; color: #1C211A; border: 1px solid #A4B885; font-size: 11.5px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; padding: 6px 14px; border-radius: 999px; margin-bottom: 18px; }
    .info-table { width: 100%; border-collapse: collapse; margin-bottom: 24px; }
    .info-table td { padding: 11px 12px; font-size: 14px; border-bottom: 1px solid #F0EEE6; }
    .info-table td.label { font-weight: 700; color: #525B4C; width: 145px; text-transform: uppercase; font-size: 11px; letter-spacing: 0.04em; }
    .info-table td.val { color: #1C211A; }
    .message-box { background: #FFF9F2; border-left: 4px solid #D46D25; padding: 18px 20px; border-radius: 12px; margin-top: 8px; margin-bottom: 24px; }
    .message-box h4 { margin: 0 0 8px 0; font-size: 12px; font-weight: 700; color: #D46D25; text-transform: uppercase; letter-spacing: 0.05em; }
    .message-box p { margin: 0; font-size: 14.5px; line-height: 1.6; white-space: pre-wrap; color: #1C211A; }
    .cta-btn { display: inline-block; background: #D46D25; color: #FFFFFF !important; text-decoration: none; font-weight: 700; font-size: 13.5px; padding: 13px 26px; border-radius: 999px; margin-bottom: 12px; }
    .footer { background: #F4F6EF; padding: 16px 28px; font-size: 11.5px; color: #525B4C; border-top: 1px solid #E3E7DC; }
  </style>
</head>
<body>
  <div class="email-container">
    <div class="header">
      <h1>Géza.ai — Web, Automation &amp; AI Services</h1>
      <p>New Potential Client Inquiry Alert</p>
    </div>
    <div class="content">
      <span class="badge">${escapeHtml(rawService)}</span>
      <table class="info-table">
        <tr>
          <td class="label">Client Name</td>
          <td class="val"><strong>${escapeHtml(rawName)}</strong></td>
        </tr>
        <tr>
          <td class="label">Email Address</td>
          <td class="val"><a href="mailto:${escapeHtml(rawEmail)}" style="color:#D46D25;font-weight:600;">${escapeHtml(rawEmail)}</a></td>
        </tr>
        <tr>
          <td class="label">Business / Company</td>
          <td class="val">${rawCompany ? escapeHtml(rawCompany) : '<em style="color:#7D8677;">Not specified</em>'}</td>
        </tr>
        <tr>
          <td class="label">Service Pillar</td>
          <td class="val">${escapeHtml(rawService)}</td>
        </tr>
        <tr>
          <td class="label">Phone</td>
          <td class="val">${rawPhone ? escapeHtml(rawPhone) : '<em style="color:#7D8677;">Not provided</em>'}</td>
        </tr>
        <tr>
          <td class="label">Received At</td>
          <td class="val">${escapeHtml(formattedDate)}</td>
        </tr>
        <tr>
          <td class="label">Reference ID</td>
          <td class="val"><code>${escapeHtml(submissionId)}</code></td>
        </tr>
      </table>

      <div class="message-box">
        <h4>Project Details &amp; Goals:</h4>
        <p>${escapeHtml(rawMessage)}</p>
      </div>

      <div>
        <a href="mailto:${escapeHtml(rawEmail)}?subject=${encodeURIComponent('Re: ' + rawService + ' — Géza Horváth')}" class="cta-btn">
          Reply to ${escapeHtml(rawName)} &rarr;
        </a>
      </div>
    </div>
    <div class="footer">
      Saved to SQLite (<code>~/services-ai/contacts.sqlite</code>) &amp; JSONL log. Automated via n8n on Mac mini M4.
    </div>
  </div>
</body>
</html>`;

const dbRecord = {
  submissionId: submissionId,
  name: rawName,
  email: rawEmail,
  company: rawCompany,
  serviceInterest: rawService,
  phone: rawPhone,
  message: rawMessage,
  source: rawSource
};

const dbBase64 = Buffer.from(JSON.stringify(dbRecord)).toString('base64');

return {
  json: {
    submissionId: submissionId,
    name: rawName,
    email: rawEmail,
    company: rawCompany,
    serviceInterest: rawService,
    phone: rawPhone,
    message: rawMessage,
    source: rawSource,
    dbBase64: dbBase64,
    createdAt: now.toISOString(),
    formattedDate: formattedDate,
    emailSubject: emailSubject,
    emailHtml: emailHtml
  }
};

